/**
 * Generated by ELF Studio - Native Windose OS ELF Program
 * Target: Windose Kernel API v10 (Cosmos NativeAOT)
 * Include: kernel.h (System/ELF/programs/include/kernel.h)
 * Screen: WindoseLogon (640x480)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "kernel.h"

/* Component Handles */
static handle_t main_win = 0;
static handle_t h_lbl_logo = 0;
static handle_t h_lbl_sub = 0;
static handle_t h_inp_user = 0;
static handle_t h_inp_pass = 0;
static handle_t h_chk_remember = 0;
static handle_t h_btn_login = 0;
static handle_t h_btn_shutdown = 0;
static handle_t h_status_bar = 0;

/* Signal Callbacks */
static void on_chk_remember_event(void) {
    k_write_file("/dev/log", "[EVENT] on_chk_remember_event dispatched\n", 0);
    int checked = k_get_checked(h_chk_remember);
    (void)checked;
}

static void on_login_click(void) {
    k_write_file("/dev/log", "[EVENT] on_login_click dispatched\n", 0);
    // Action logic for button btn_login
}

static void on_shutdown_click(void) {
    k_write_file("/dev/log", "[EVENT] on_shutdown_click dispatched\n", 0);
    // Action logic for button btn_shutdown
}

int main(int argc, char **argv) {
    main_win = k_create_window(640, 480, "WindoseLogon");
    if (!main_win) return 1;

    /* login_card (panel) */
    k_fill_rect(main_win, 140, 80, 360, 320, 0xFFFFFFFF);

    /* lbl_logo (label) */
    h_lbl_logo = k_create_label(main_win, 160, 105, "🪐 WINDOSE 7 AERO");

    /* lbl_sub (label) */
    h_lbl_sub = k_create_label(main_win, 160, 140, "Please authenticate to initialize desktop session");

    /* inp_user (entry) */
    h_inp_user = k_create_textfield(main_win, 160, 175, 320);
    k_textfield_setup(h_inp_user, 256, 0, 0);
    k_set_text(h_inp_user, "Administrator");

    /* inp_pass (entry) */
    h_inp_pass = k_create_textfield(main_win, 160, 230, 320);
    k_textfield_setup(h_inp_pass, 256, 0, 0);
    k_set_text(h_inp_pass, "••••••••••••");

    /* chk_remember (checkbox) */
    h_chk_remember = k_create_checkbox(main_win, 160, 280, "Remember Credentials");
    k_set_checked(h_chk_remember, 1);

    /* btn_login (button) */
    h_btn_login = k_create_button(main_win, 160, 325, 150, 42, "Log On ➔");

    /* btn_shutdown (button) */
    h_btn_shutdown = k_create_button(main_win, 330, 325, 150, 42, "Shut Down");

    /* status_bar (statusbar) */
    h_status_bar = k_statusbar_create(main_win, 0, 456, 640);
    k_status_add_panel(h_status_bar, "Windose 7 Aero Edition | Cosmos Protected Kernel | ACPI Ready", 640);

    /* Main Windose Event Loop */
    for (;;) {
        Event e;
        while (k_poll_event(&e)) {
            if (e.type == EV_CLOSE && e.handle == main_win) {
                k_close(main_win);
                return 0;
            }
            if (e.type == EV_CLICK) {
                if (e.handle == h_chk_remember) {
                    on_chk_remember_event();
                }
                if (e.handle == h_btn_login) {
                    on_login_click();
                }
                if (e.handle == h_btn_shutdown) {
                    on_shutdown_click();
                }
            }
        }
        k_sleep(10); // Prevent 100% CPU starvation
    }
}